func ParseEnvironment(raw string) (map[string]string, error) {
	if strings.TrimSpace(raw) == "" {
		return nil, nil
	}
	var environment map[string]string
	if err := yaml.Unmarshal([]byte(raw), &environment); err != nil {
		return nil, fmt.Errorf("parse SEMREL_PLUGIN_ENV: %w", err)
	}
	for key := range environment {
		if !environmentNamePattern.MatchString(key) {
			return nil, fmt.Errorf("SEMREL_PLUGIN_ENV contains invalid variable name %q", key)
		}
		if strings.ContainsRune(environment[key], '\x00') {
			return nil, fmt.Errorf("SEMREL_PLUGIN_ENV value for %q contains a NUL byte", key)
		}
	}
	return environment, nil
}

func Execute(parent context.Context, cfg Config, stdout, stderr io.Writer) error {
	commands, phase, err := selectCommands(cfg)
	if err != nil {
		return err
	}
	if cfg.DryRun && !cfg.RunInDryRun {
		for _, command := range commands {
			_, _ = fmt.Fprintf(stderr, "hook-exec: dry-run: skipped %s command: %s\n", phase, command)
		}
		return nil
	}

	timeout := cfg.Timeout
	if timeout <= 0 {
		timeout = 5 * time.Minute
	}
	shell := cfg.Shell
	if shell == "" {
		if runtime.GOOS == "windows" {
			shell = "cmd"
		} else {
			shell = "sh"
		}
	}

	for _, rawCommand := range commands {
		command := expandTemplate(rawCommand, cfg.Template, shell)
		ctx, cancel := context.WithTimeout(parent, timeout)
		err := runCommand(ctx, shell, command, cfg.WorkingDirectory, cfg.Environment, stdout, stderr)
		timedOut := errors.Is(ctx.Err(), context.DeadlineExceeded)
		cancel()
		if timedOut {
			return fmt.Errorf("%s command timed out after %s", phase, timeout)
		}
		if err != nil {
			return fmt.Errorf("%s command failed: %w", phase, err)
		}
	}
	return nil
}

func selectCommands(cfg Config) ([]string, string, error) {
	if strings.TrimSpace(cfg.Command) != "" {
		return []string{cfg.Command}, normalizedPhase(cfg.Phase, "configured"), nil
	}

	groups := map[string][]string{
		"condition": nonEmpty(cfg.VerifyConditionsCmd),
		"generator": nonEmpty(cfg.GenerateNotesCmd),
		"pre-tag":   nonEmpty(cfg.VerifyReleaseCmd, cfg.PrepareCmd),
		"release":   nonEmpty(cfg.PublishCmd, cfg.SuccessCmd),
	}

	phase := normalizedPhase(cfg.Phase, "")
	if phase != "" {
		commands, ok := groups[phase]
		if !ok {
			return nil, "", fmt.Errorf("unsupported phase %q; supported phases are condition, generator, pre-tag, and release", cfg.Phase)
		}
		if len(commands) == 0 {
			return nil, "", fmt.Errorf("no command configured for phase %q", phase)
		}
		return commands, phase, nil
	}

	var selectedPhase string
	var selected []string
	for candidate, commands := range groups {
		if len(commands) == 0 {
			continue
		}
		if selectedPhase != "" {
			return nil, "", errors.New("multiple lifecycle phases are configured; set SEMREL_PLUGIN_PHASE or use SEMREL_PLUGIN_CMD")
		}
		selectedPhase = candidate
		selected = commands
	}
	if selectedPhase != "" {
		return selected, selectedPhase, nil
	}
	if cfg.AnalyzeCommitsCmd != "" {
		return nil, "", errors.New("analyzeCommitsCmd is unsupported because semrel has no external analyzer plugin phase")
	}
	if cfg.FailCmd != "" {
		return nil, "", errors.New("failCmd is unsupported because semrel does not invoke plugins after pipeline failure")
	}
	return nil, "", errors.New("SEMREL_PLUGIN_CMD or a supported lifecycle command is required")
}

func runCommand(
	ctx context.Context,
	shell string,
	command string,
	workingDirectory string,
	environment map[string]string,
	stdout io.Writer,
	stderr io.Writer,
) error {
	args := shellArguments(shell, command)
	process := exec.CommandContext(ctx, shell, args...)
	configureCommand(process)
	process.Cancel = func() error {
		return terminateCommand(process)
	}
	process.WaitDelay = time.Second
	process.Stdout = stdout
	process.Stderr = stderr
	process.Stdin = os.Stdin
	if workingDirectory != "" {
		absolute, err := filepath.Abs(workingDirectory)
		if err != nil {
			return fmt.Errorf("resolve working directory: %w", err)
		}
		info, err := os.Stat(absolute)
		if err != nil {
			return fmt.Errorf("working directory: %w", err)
		}
		if !info.IsDir() {
			return fmt.Errorf("working directory %q is not a directory", workingDirectory)
		}
		process.Dir = absolute
	}
	process.Env = mergeEnvironment(os.Environ(), environment)
	return process.Run()
}

func shellArguments(shell, command string) []string {
	base := strings.ToLower(filepath.Base(shell))
	switch base {
	case "cmd", "cmd.exe":
		return []string{"/D", "/S", "/C", command}
	case "pwsh", "pwsh.exe", "powershell", "powershell.exe":
		return []string{"-NoLogo", "-NoProfile", "-NonInteractive", "-Command", command}
	default:
		return []string{"-c", command}
	}
}

func mergeEnvironment(base []string, overrides map[string]string) []string {
	result := make([]string, 0, len(base)+len(overrides))
	positions := make(map[string]int, len(base))
	for _, entry := range base {
		key, _, _ := strings.Cut(entry, "=")
		positions[key] = len(result)
		result = append(result, entry)
	}
	for key, value := range overrides {
		entry := key + "=" + value
		if index, ok := positions[key]; ok {
			result[index] = entry
		} else {
			positions[key] = len(result)
			result = append(result, entry)
		}
	}
	return result
}

func expandTemplate(command string, data TemplateData, shell string) string {
	values := map[string]string{
		"nextRelease.version": data.NextVersion,
		"lastRelease.version": data.CurrentVersion,
		"gitTag":              data.TagName,
		"tag":                 data.TagName,
		"channel":             data.Branch,
		"branch":              data.Branch,
		"date":                data.Date,
	}
	for key, value := range values {
		command = strings.ReplaceAll(command, "${"+key+"}", quoteForShell(value, shell))
	}
	return command
}

func quoteForShell(value, shell string) string {
	base := strings.ToLower(filepath.Base(shell))
	if base == "cmd" || base == "cmd.exe" {
		return `"` + strings.ReplaceAll(value, `"`, `""`) + `"`
	}
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

func normalizedPhase(phase, fallback string) string {
	phase = strings.ToLower(strings.TrimSpace(phase))
	switch phase {
	case "prepare", "updater":
		return "pre-tag"
	case "publish", "success":
		return "release"
	case "verify", "verify-conditions":
		return "condition"
	case "generate", "generate-notes":
		return "generator"
	case "":
		return fallback
	default:
		return phase
	}
}

func nonEmpty(values ...string) []string {
	result := make([]string, 0, len(values))
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			result = append(result, value)
		}
	}
	return result
}
